175	void AGBHUD::ResetMenuMouse()
176	{
177		MenuHits.Reset();
178		MenuHitsMenu = EGBMenu::None;
179		MenuHitsPage = -1;
180		bMenuHitsChoosing = false;
181		// The first position read after opening is only a baseline: an idle mouse must not steal the keyboard cursor.
182		bHasMenuMouse = false;
