471	TArray<FName> AGBHUD::GetInventoryList(AGBPlayerCharacter* Player) const
472	{
473		TArray<FName> Result;
474		const UGBInventoryComponent* Inventory = Player ? Player->GetInventory() : nullptr;
475		if (!Inventory)
476		{
477			return Result;
478		}
479		if (const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this))
480		{
481			for (const FGBItemDefinition& Def : Data->GetItems())
482			{
483				if (Inventory->GetCount(Def.Id) > 0)
484				{
485					Result.Add(Def.Id);
486				}
487			}
488		}
489		// Items no longer in the data (after a reload) are still listed, at the end.
490		for (const TPair<FName, int32>& Entry : Inventory->GetItems())
491		{
492			if (Entry.Value > 0 && !Result.Contains(Entry.Key))
493			{
494				Result.Add(Entry.Key);
495			}
496		}
497		return Result;
498	}
