553	TArray<AGBHUD::FSkillNodeRef> AGBHUD::GetSkillNodes() const
554	{
555		TArray<FSkillNodeRef> Result;
556		if (const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this))
557		{
558			for (const FGBSkillNodeDefinition& Def : Data->GetSkillNodes())
559			{
560				FSkillNodeRef Ref;
561				Ref.Id = Def.Id;
562				Ref.Tree = GBHudMenuLocal::IsWeaponTree(Def.Tree) ? 1 : 0;
563				Ref.Column = FMath::Max(0, Def.Column);
564				Ref.Row = FMath::Max(0, Def.Row);
565				Result.Add(Ref);
566			}
567		}
568		return Result;
569	}
570	
571	void AGBHUD::NavigateSkills(FIntPoint Direction)
572	{
573		const TArray<FSkillNodeRef> Nodes = GetSkillNodes();
574		if (Nodes.Num() == 0 || Direction == FIntPoint::ZeroValue)
575		{
576			return;
577		}
578		const FSkillNodeRef* Current = Nodes.FindByPredicate([this](const FSkillNodeRef& Node) { return Node.Id == MenuState.SkillCursor; });
579		if (!Current)
580		{
581			MenuState.SkillCursor = Nodes[0].Id;
582			return;
583		}
584	
585		// Both trees on one grid (the weapon tree to the right of the spell tree); pick the nearest node in the pressed direction.
586		int32 MaxSpellColumn = 0;
587		for (const FSkillNodeRef& Node : Nodes)
588		{
589			if (Node.Tree == 0)
590			{
591				MaxSpellColumn = FMath::Max(MaxSpellColumn, Node.Column);
592			}
593		}
594		auto GridPos = [MaxSpellColumn](const FSkillNodeRef& Node)
595		{
596			return FVector2D(Node.Tree * (MaxSpellColumn + 2) + Node.Column, Node.Row);
597		};
598		const FVector2D Dir(Direction.X, Direction.Y);
599		const FVector2D From = GridPos(*Current);
600		float BestCost = TNumericLimits<float>::Max();
601		FName Best = NAME_None;
602		for (const FSkillNodeRef& Node : Nodes)
603		{
604			if (Node.Id == Current->Id)
605			{
606				continue;
607			}
608			const FVector2D Delta = GridPos(Node) - From;
609			const float Along = FVector2D::DotProduct(Delta, Dir);
610			if (Along <= 0.f)
611			{
612				continue;
613			}
614			const float Across = FMath::Abs(FVector2D::CrossProduct(Delta, Dir));
615			const float Cost = Along + 2.f * Across;
616			if (Cost < BestCost)
617			{
618				BestCost = Cost;
619				Best = Node.Id;
620			}
621		}
622		if (Best != NAME_None)
623		{
624			MenuState.SkillCursor = Best;
625		}
626	}
