629	
630	void AGBHUD::ConfirmItem(AGBPlayerCharacter* Player)
631	{
632		using namespace GBHudMenuLocal;
633		UGBInventoryComponent* Inventory = Player ? Player->GetInventory() : nullptr;
634		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
635		const TArray<FName> List = GetInventoryList(Player);
636		if (!Inventory || List.Num() == 0)
637		{
638			return;
639		}
640		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
641		const FName ItemId = List[MenuState.Cursor];
642		const FGBItemDefinition* Def = Data ? Data->FindItem(ItemId) : nullptr;
643		if (!Def)
644		{
645			ShowMessage(TEXT("Unknown item"), 1.5f);
646			return;
647		}
648	
649		switch (Def->Type)
650		{
651		case EGBItemType::Consumable:
652			if (!Inventory->UseItem(ItemId))
653			{
654				ShowMessage(TEXT("Cannot use that now"), 1.5f);
655			}
656			break;
657		case EGBItemType::Throwable:
658			ShowMessage(TEXT("Throw it with [F] (quick-use)"), 2.f);
659			break;
660		case EGBItemType::Armor:
661			if (!Inventory->EquipArmor(Inventory->GetEquippedArmor() == ItemId ? NAME_None : ItemId))
662			{
663				ShowMessage(TEXT("Cannot equip that"), 1.5f);
664			}
665			break;
666		case EGBItemType::Material:
667		case EGBItemType::KeyItem:
668			if (MenuState.PendingCombine == NAME_None)
669			{
670				MenuState.PendingCombine = ItemId;
671			}
672			else if (MenuState.PendingCombine == ItemId)
673			{
674				MenuState.PendingCombine = NAME_None;
675			}
676			else
677			{
678				const FName Other = MenuState.PendingCombine;
679				MenuState.PendingCombine = NAME_None;
680				const FGBRecipeDefinition* Recipe = Inventory->FindRecipe(Other, ItemId);
681				// Copy what the toast needs before combining: the recipe pointer belongs to the data tables.
682				FString ResultName;
683				if (Recipe)
684				{
685					if (Recipe->ResultItem != NAME_None)
686					{
687						ResultName = ItemName(Data, Recipe->ResultItem);
688					}
689					else if (Recipe->ResultWeapon != NAME_None)
690					{
691						const FGBWeaponDefinition* Weapon = Data->FindWeapon(Recipe->ResultWeapon);
692						ResultName = (Weapon && !Weapon->DisplayName.IsEmpty()) ? Weapon->DisplayName : Recipe->ResultWeapon.ToString();
693					}
694				}
695				if (Recipe && Inventory->TryCombine(Other, ItemId))
696				{
697					ShowMessage(ResultName.IsEmpty() ? FString(TEXT("Combined")) : FString::Printf(TEXT("Created %s"), *ResultName), 2.5f);
698				}
699				else
700				{
701					ShowMessage(TEXT("These do not combine"), 1.5f);
702				}
703			}
704			break;
705		default:
706			break;
707		}
708	}
709	
710	void AGBHUD::ConfirmWeapon(AGBPlayerCharacter* Player)
711	{
712		UGBEquipmentComponent* Equipment = Player ? Player->GetEquipment() : nullptr;
713		const TArray<FName> List = GetWeaponList(Player);
714		if (!Equipment || List.Num() == 0)
715		{
716			return;
717		}
718		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
719		const FName WeaponId = List[MenuState.Cursor];
720		const FString Name = GBHudMenuLocal::WeaponName(UGBDataSubsystem::Get(this), WeaponId);
721		if (Equipment->IsWeaponEquipped(WeaponId))
722		{
723			ShowMessage(FString::Printf(TEXT("%s is already equipped"), *Name), 1.5f);
724		}
725		else if (Equipment->EquipOwnedWeapon(WeaponId))
726		{
727			ShowMessage(FString::Printf(TEXT("Equipped %s"), *Name), 2.f);
728		}
729		else
730		{
731			ShowMessage(TEXT("Cannot change weapons right now"), 1.5f);
732		}
733	}
734	
735	void AGBHUD::ConfirmSpellSlot(AGBPlayerCharacter* Player)
736	{
737		UGBSpellbookComponent* Spellbook = Player ? Player->GetSpellbook() : nullptr;
738		if (!Spellbook)
739		{
740			return;
741		}
742		const int32 NumSlots = UGBSpellbookComponent::NumSlots;
743		if (MenuState.bChoosingSpell)
744		{
745			const TArray<FName> Options = GetAssignableSpells(Player);
746			if (Options.IsValidIndex(MenuState.SubCursor) && MenuState.Cursor < NumSlots)
747			{
748				if (!Spellbook->EquipSpell(MenuState.Cursor, Options[MenuState.SubCursor]))
749				{
750					ShowMessage(TEXT("Cannot equip that spell"), 1.5f);
751				}
752			}
753			MenuState.bChoosingSpell = false;
754		}
755		else if (MenuState.Cursor < NumSlots)
756		{
757			const TArray<FName> Options = GetAssignableSpells(Player);
758			MenuState.bChoosingSpell = true;
759			MenuState.SubCursor = FMath::Max(0, Options.IndexOfByKey(Spellbook->GetSlotSpell(MenuState.Cursor)));
760		}
761		else
762		{
763			// The enchant slot: cycle its element Fire -> Lightning -> Ice.
764			EGBElement Next = EGBElement::Fire;
765			switch (Spellbook->GetEnchantElement())
766			{
767			case EGBElement::Fire: Next = EGBElement::Lightning; break;
768			case EGBElement::Lightning: Next = EGBElement::Ice; break;
769			default: Next = EGBElement::Fire; break;
770			}
771			Spellbook->SetEnchantElement(Next);
772		}
773	}
774	
775	void AGBHUD::ConfirmSkill(AGBPlayerCharacter* Player)
776	{
777		UGBSkillTreeComponent* SkillTree = Player ? Player->GetSkillTree() : nullptr;
778		const FName NodeId = MenuState.SkillCursor;
779		if (!SkillTree || NodeId == NAME_None)
780		{
781			return;
782		}
783		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
784		const EGBSkillUnlockResult Result = SkillTree->Unlock(NodeId);
785		if (Result == EGBSkillUnlockResult::Ok)
786		{
787			ShowMessage(FString::Printf(TEXT("Unlocked %s (rank %d)"), *GBHudMenuLocal::SkillName(Data, NodeId), SkillTree->GetRank(NodeId)), 2.f);
788		}
789		else
790		{
791			ShowMessage(GBHudMenuLocal::SkillResultText(Data, NodeId, Result), 2.f);
792		}
793	}
