797	float AGBHUD::DrawWrapped(const FString& Text, const FLinearColor& Color, float X, float Y, float MaxWidth, float SizePx, bool bShadow)
798	{
799		TArray<FString> Words;
800		Text.ParseIntoArrayWS(Words);
801		const float LineH = FMath::Max(MeasureLabel(TEXT("Ag"), SizePx).Y, 1.f);
802		float CurY = Y;
803		FString Line;
804		for (const FString& Word : Words)
805		{
806			const FString Candidate = Line.IsEmpty() ? Word : Line + TEXT(" ") + Word;
807			if (!Line.IsEmpty() && MeasureLabel(Candidate, SizePx).X > MaxWidth)
808			{
809				DrawLabel(Line, Color, X, CurY, SizePx, 0.f, bShadow);
810				CurY += LineH;
811				Line = Word;
812			}
813			else
814			{
815				Line = Candidate;
816			}
817		}
818		if (!Line.IsEmpty())
819		{
820			DrawLabel(Line, Color, X, CurY, SizePx, 0.f, bShadow);
821			CurY += LineH;
822		}
823		return CurY - Y;
824	}
