147	void UGBSkillTreeComponent::RemoveAllModifiers()
148	{
149		UGBStatsComponent* Stats = UGBStatsComponent::Find(GetOwner());
150		if (!Stats)
151		{
152			return;
153		}
154		for (const TPair<FName, int32>& Pair : Ranks)
155		{
156			Stats->RemoveModifiers(ModifierSource(Pair.Key));
157		}
158	}
