470	
471	TArray<FName> AGBHUD::GetInventoryList(AGBPlayerCharacter* Player) const
472	{
473		TArray<FName> Result;
474		const UGBInventoryComponent* Inventory = Player ? Player->GetInventory() : nullptr;
475		if (!Inventory)
476		{
477			return Result;
478		}
479		if (const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this))
480		{
481			for (const FGBItemDefinition& Def : Data->GetItems())
482			{
483				if (Inventory->GetCount(Def.Id) > 0)
484				{
485					Result.Add(Def.Id);
486				}
487			}
488		}
489		// Items no longer in the data (after a reload) are still listed, at the end.
490		for (const TPair<FName, int32>& Entry : Inventory->GetItems())
491		{
492			if (Entry.Value > 0 && !Result.Contains(Entry.Key))
493			{
494				Result.Add(Entry.Key);
495			}
496		}
497		return Result;
498	}
499	
500	TArray<FName> AGBHUD::GetWeaponList(AGBPlayerCharacter* Player) const
501	{
502		TArray<FName> Result;
503		const UGBEquipmentComponent* Equipment = Player ? Player->GetEquipment() : nullptr;
504		if (!Equipment)
505		{
506			return Result;
507		}
508		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
509		static const EGBHeldSlot Order[] = { EGBHeldSlot::Staff, EGBHeldSlot::Gun, EGBHeldSlot::Sword };
510		for (const EGBHeldSlot Slot : Order)
511		{
512			for (const FName& WeaponId : Equipment->GetOwnedWeapons())
513			{
514				const FGBWeaponDefinition* Def = Data ? Data->FindWeapon(WeaponId) : nullptr;
515				if (Def && Def->Slot == Slot)
516				{
517					Result.AddUnique(WeaponId);
518				}
519			}
520		}
521		// Weapons no longer in the data (after a reload) are still listed, at the end.
522		for (const FName& WeaponId : Equipment->GetOwnedWeapons())
523		{
524			if (WeaponId != NAME_None)
525			{
526				Result.AddUnique(WeaponId);
527			}
528		}
529		return Result;
530	}
531	
532	TArray<FName> AGBHUD::GetAssignableSpells(AGBPlayerCharacter* Player) const
533	{
534		TArray<FName> Result;
535		Result.Add(NAME_None);
536		const UGBSpellbookComponent* Spellbook = Player ? Player->GetSpellbook() : nullptr;
537		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
538		if (!Spellbook || !Data)
539		{
540			return Result;
541		}
542		for (const FName& SpellId : Spellbook->GetKnownSpells())
543		{
544			const FGBSpellDefinition* Def = Data->FindSpell(SpellId);
545			if (Def && !Def->bPassive && !Def->bRequiresGun && SpellId != Spellbook->GetEnchantSpell())
546			{
547				Result.Add(SpellId);
548			}
549		}
550		return Result;
551	}
552	
553	TArray<AGBHUD::FSkillNodeRef> AGBHUD::GetSkillNodes() const
554	{
555		TArray<FSkillNodeRef> Result;
556		if (const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this))
557		{
558			for (const FGBSkillNodeDefinition& Def : Data->GetSkillNodes())
559			{
560				FSkillNodeRef Ref;
561				Ref.Id = Def.Id;
562				Ref.Tree = GBHudMenuLocal::IsWeaponTree(Def.Tree) ? 1 : 0;
563				Ref.Column = FMath::Max(0, Def.Column);
564				Ref.Row = FMath::Max(0, Def.Row);
565				Result.Add(Ref);
566			}
567		}
568		return Result;
569	}
570	
571	void AGBHUD::NavigateSkills(FIntPoint Direction)
572	{
573		const TArray<FSkillNodeRef> Nodes = GetSkillNodes();
574		if (Nodes.Num() == 0 || Direction == FIntPoint::ZeroValue)
575		{
576			return;
577		}
578		const FSkillNodeRef* Current = Nodes.FindByPredicate([this](const FSkillNodeRef& Node) { return Node.Id == MenuState.SkillCursor; });
579		if (!Current)
580		{
581			MenuState.SkillCursor = Nodes[0].Id;
582			return;
583		}
584	
585		// Both trees on one grid (the weapon tree to the right of the spell tree); pick the nearest node in the pressed direction.
586		int32 MaxSpellColumn = 0;
587		for (const FSkillNodeRef& Node : Nodes)
588		{
589			if (Node.Tree == 0)
590			{
591				MaxSpellColumn = FMath::Max(MaxSpellColumn, Node.Column);
592			}
593		}
594		auto GridPos = [MaxSpellColumn](const FSkillNodeRef& Node)
595		{
596			return FVector2D(Node.Tree * (MaxSpellColumn + 2) + Node.Column, Node.Row);
597		};
598		const FVector2D Dir(Direction.X, Direction.Y);
599		const FVector2D From = GridPos(*Current);
600		float BestCost = TNumericLimits<float>::Max();
601		FName Best = NAME_None;
602		for (const FSkillNodeRef& Node : Nodes)
603		{
604			if (Node.Id == Current->Id)
605			{
606				continue;
607			}
608			const FVector2D Delta = GridPos(Node) - From;
609			const float Along = FVector2D::DotProduct(Delta, Dir);
610			if (Along <= 0.f)
611			{
612				continue;
613			}
614			const float Across = FMath::Abs(FVector2D::CrossProduct(Delta, Dir));
615			const float Cost = Along + 2.f * Across;
616			if (Cost < BestCost)
617			{
618				BestCost = Cost;
619				Best = Node.Id;
620			}
621		}
622		if (Best != NAME_None)
623		{
624			MenuState.SkillCursor = Best;
625		}
626	}
627	
628	// ======================================================================== confirm actions
629	
630	void AGBHUD::ConfirmItem(AGBPlayerCharacter* Player)
631	{
632		using namespace GBHudMenuLocal;
633		UGBInventoryComponent* Inventory = Player ? Player->GetInventory() : nullptr;
634		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
635		const TArray<FName> List = GetInventoryList(Player);
636		if (!Inventory || List.Num() == 0)
637		{
638			return;
639		}
640		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
641		const FName ItemId = List[MenuState.Cursor];
642		const FGBItemDefinition* Def = Data ? Data->FindItem(ItemId) : nullptr;
643		if (!Def)
644		{
645			ShowMessage(TEXT("Unknown item"), 1.5f);
646			return;
647		}
648	
649		switch (Def->Type)
650		{
651		case EGBItemType::Consumable:
652			if (!Inventory->UseItem(ItemId))
653			{
654				ShowMessage(TEXT("Cannot use that now"), 1.5f);
655			}
656			break;
657		case EGBItemType::Throwable:
658			ShowMessage(TEXT("Throw it with [F] (quick-use)"), 2.f);
659			break;
660		case EGBItemType::Armor:
661			if (!Inventory->EquipArmor(Inventory->GetEquippedArmor() == ItemId ? NAME_None : ItemId))
662			{
663				ShowMessage(TEXT("Cannot equip that"), 1.5f);
664			}
665			break;
666		case EGBItemType::Material:
667		case EGBItemType::KeyItem:
668			if (MenuState.PendingCombine == NAME_None)
669			{
670				MenuState.PendingCombine = ItemId;
671			}
672			else if (MenuState.PendingCombine == ItemId)
673			{
674				MenuState.PendingCombine = NAME_None;
675			}
676			else
677			{
678				const FName Other = MenuState.PendingCombine;
679				MenuState.PendingCombine = NAME_None;
680				const FGBRecipeDefinition* Recipe = Inventory->FindRecipe(Other, ItemId);
681				// Copy what the toast needs before combining: the recipe pointer belongs to the data tables.
682				FString ResultName;
683				if (Recipe)
684				{
685					if (Recipe->ResultItem != NAME_None)
686					{
687						ResultName = ItemName(Data, Recipe->ResultItem);
688					}
689					else if (Recipe->ResultWeapon != NAME_None)
690					{
691						const FGBWeaponDefinition* Weapon = Data->FindWeapon(Recipe->ResultWeapon);
692						ResultName = (Weapon && !Weapon->DisplayName.IsEmpty()) ? Weapon->DisplayName : Recipe->ResultWeapon.ToString();
693					}
694				}
695				if (Recipe && Inventory->TryCombine(Other, ItemId))
696				{
697					ShowMessage(ResultName.IsEmpty() ? FString(TEXT("Combined")) : FString::Printf(TEXT("Created %s"), *ResultName), 2.5f);
698				}
699				else
700				{
701					ShowMessage(TEXT("These do not combine"), 1.5f);
702				}
703			}
704			break;
705		default:
706			break;
707		}
708	}
709	
710	void AGBHUD::ConfirmWeapon(AGBPlayerCharacter* Player)
711	{
712		UGBEquipmentComponent* Equipment = Player ? Player->GetEquipment() : nullptr;
713		const TArray<FName> List = GetWeaponList(Player);
714		if (!Equipment || List.Num() == 0)
715		{
716			return;
717		}
718		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
719		const FName WeaponId = List[MenuState.Cursor];
720		const FString Name = GBHudMenuLocal::WeaponName(UGBDataSubsystem::Get(this), WeaponId);
721		if (Equipment->IsWeaponEquipped(WeaponId))
722		{
723			ShowMessage(FString::Printf(TEXT("%s is already equipped"), *Name), 1.5f);
724		}
725		else if (Equipment->EquipOwnedWeapon(WeaponId))
726		{
727			ShowMessage(FString::Printf(TEXT("Equipped %s"), *Name), 2.f);
728		}
729		else
730		{
731			ShowMessage(TEXT("Cannot change weapons right now"), 1.5f);
732		}
733	}
734	
735	void AGBHUD::ConfirmSpellSlot(AGBPlayerCharacter* Player)
736	{
737		UGBSpellbookComponent* Spellbook = Player ? Player->GetSpellbook() : nullptr;
738		if (!Spellbook)
739		{
740			return;
741		}
742		const int32 NumSlots = UGBSpellbookComponent::NumSlots;
743		if (MenuState.bChoosingSpell)
744		{
745			const TArray<FName> Options = GetAssignableSpells(Player);
746			if (Options.IsValidIndex(MenuState.SubCursor) && MenuState.Cursor < NumSlots)
747			{
748				if (!Spellbook->EquipSpell(MenuState.Cursor, Options[MenuState.SubCursor]))
749				{
750					ShowMessage(TEXT("Cannot equip that spell"), 1.5f);
751				}
752			}
753			MenuState.bChoosingSpell = false;
754		}
755		else if (MenuState.Cursor < NumSlots)
756		{
757			const TArray<FName> Options = GetAssignableSpells(Player);
758			MenuState.bChoosingSpell = true;
759			MenuState.SubCursor = FMath::Max(0, Options.IndexOfByKey(Spellbook->GetSlotSpell(MenuState.Cursor)));
760		}
761		else
762		{
763			// The enchant slot: cycle its element Fire -> Lightning -> Ice.
764			EGBElement Next = EGBElement::Fire;
765			switch (Spellbook->GetEnchantElement())
766			{
767			case EGBElement::Fire: Next = EGBElement::Lightning; break;
768			case EGBElement::Lightning: Next = EGBElement::Ice; break;
769			default: Next = EGBElement::Fire; break;
770			}
771			Spellbook->SetEnchantElement(Next);
772		}
773	}
774	
775	void AGBHUD::ConfirmSkill(AGBPlayerCharacter* Player)
776	{
777		UGBSkillTreeComponent* SkillTree = Player ? Player->GetSkillTree() : nullptr;
778		const FName NodeId = MenuState.SkillCursor;
779		if (!SkillTree || NodeId == NAME_None)
780		{
781			return;
782		}
783		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
784		const EGBSkillUnlockResult Result = SkillTree->Unlock(NodeId);
785		if (Result == EGBSkillUnlockResult::Ok)
786		{
787			ShowMessage(FString::Printf(TEXT("Unlocked %s (rank %d)"), *GBHudMenuLocal::SkillName(Data, NodeId), SkillTree->GetRank(NodeId)), 2.f);
788		}
789		else
790		{
791			ShowMessage(GBHudMenuLocal::SkillResultText(Data, NodeId, Result), 2.f);
792		}
793	}
